	 */
	ownerSessionId?: string;
	/**
	 * Keep the tab live across turn settle and idle close. Recorded on the
	 * tab when created (never on reuse) so a later caller cannot silently
	 * extend another session's tab lifetime.
	 */
	persist?: boolean;
